const localeOrder: Language[] = ['es', 'fr', 'pt', 'ar', 'sw', 'ha', 'yo', 'ig'];
const dictionaries: Partial<Record<Language, Record<string, string>>> = {};
for (const [key, values] of Object.entries(rows)) {
  localeOrder.forEach((locale, index) => {
    dictionaries[locale] ??= {};
    dictionaries[locale]![key] = values[index];
  });
}

export function translate(text: string): string {
  const language = getLanguage();
  return dictionaries[language]?.[text.trim().replace(/\s+/g, ' ')] ?? text;
}

function translatePreservingWhitespace(value: string): string {
  const leading = value.match(/^\s*/)?.[0] ?? '';
  const trailing = value.match(/\s*$/)?.[0] ?? '';
  const normalized = value.trim().replace(/\s+/g, ' ');
  if (!normalized) return value;
  return leading + (dictionaries[getLanguage()]?.[normalized] ?? normalized) + trailing;
}

/** A text node that refreshes when the global language preference changes. */
export function T({ children }: { children: ReactNode }) {
  const [, refresh] = useState(0);
  useEffect(() => {
    const sync = () => refresh((value) => value + 1);
    window.addEventListener('therafam:preferences', sync);
    return () => window.removeEventListener('therafam:preferences', sync);
  }, []);
  return typeof children === 'string' ? translatePreservingWhitespace(children) : children;
}

/** Re-render a parent when the language changes, for translated attributes and expressions. */
export function useLanguageRefresh() {
  const [, refresh] = useState(0);
  useEffect(() => {
    const sync = () => refresh((value) => value + 1);
    window.addEventListener('therafam:preferences', sync);
    return () => window.removeEventListener('therafam:preferences', sync);
  }, []);
}
